    Ansi ECS ΓÇö PLC & electrical control simulator

























  :root {
	color-scheme: light;
	--bg-canvas: #f0e8db;
	--bg-canvas-deep: #e3d4c0;
	--bg-surface: rgba(255, 250, 244, 0.82);
	--bg-surface-strong: #fffdfa;
	--bg-surface-muted: rgba(245, 237, 226, 0.9);
	--border-strong: #c6aa86;
	--border-muted: #e2d2bd;
	--border-soft: #efe4d6;
	--text-strong: #201814;
	--text-muted: #6c594a;
	--text-soft: #927d6a;
	--brand: #b85b2c;
	--brand-deep: #8d431d;
	--accent: #274b69;
	--accent-deep: #1c3449;
	--success: #187a51;
	--success-bg: #ebfbf2;
	--danger: #b4432a;
	--danger-bg: #fff0eb;
	--warning: #8c5b10;
	--warning-bg: #fff6e6;
	--shadow-lg: 0 18px 40px rgba(71, 43, 23, 0.12);
	--shadow-md: 0 10px 24px rgba(71, 43, 23, 0.08);
	--radius-xl: 28px;
	--radius-lg: 22px;
	--radius-md: 18px;
	--radius-sm: 14px;
	--space-1: 4px;
	--space-2: 8px;
	--space-3: 12px;
	--space-4: 16px;
	--space-5: 20px;
	--space-6: 24px;
	--space-7: 32px;
	--space-8: 40px;
	--font-ui: "Segoe UI Variable", Aptos, "Segoe UI", sans-serif;
	--font-display: Bahnschrift, "Segoe UI Variable", "Segoe UI", sans-serif;
}

* {
	box-sizing: border-box;
}

html,
body,
#root {
	min-height: 100%;
}

html {
	font-size: 16px;
}

body {
	margin: 0;
	font-family: var(--font-ui);
	color: var(--text-strong);
	background:
		radial-gradient(circle at top left, rgba(255, 255, 255, 0.75), transparent 36%),
		linear-gradient(135deg, var(--bg-canvas) 0%, var(--bg-canvas-deep) 100%);
}

body::before {
	content: "";
	position: fixed;
	inset: 0;
	background-image:
		linear-gradient(rgba(255, 255, 255, 0.22) 1px, transparent 1px),
		linear-gradient(90deg, rgba(255, 255, 255, 0.18) 1px, transparent 1px);
	background-size: 32px 32px;
	opacity: 0.28;
	pointer-events: none;
}

body,
button,
input,
select,
textarea {
	font: inherit;
}

button {
	border: 0;
	background: none;
}

button,
select,
input {
	border-radius: 999px;
}

button:disabled,
select:disabled,
input:disabled {
	cursor: not-allowed;
	opacity: 0.56;
}

button:focus-visible,
select:focus-visible,
input:focus-visible {
	outline: 3px solid rgba(39, 75, 105, 0.3);
	outline-offset: 3px;
}

p,
h1,
h2,
h3,
h4,
ol,
ul {
	margin-top: 0;
}
.app-shell {
	position: relative;
	z-index: 1;
	padding: var(--space-7) var(--space-5) var(--space-8);
}

.app-shell--playground {
	padding-top: var(--space-5);
	padding-bottom: var(--space-6);
}

.dashboard {
	width: min(1420px, 100%);
	margin: 0 auto;
	display: grid;
	gap: var(--space-6);
}

.dashboard--playground {
	width: min(1640px, 100%);
	gap: var(--space-4);
}

.panel {
	background: var(--bg-surface);
	backdrop-filter: blur(14px);
	border: 1px solid var(--border-soft);
	border-radius: var(--radius-xl);
	box-shadow: var(--shadow-md);
	padding: var(--space-6);
}

.panel__header {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	gap: var(--space-4);
	margin-bottom: var(--space-5);
}

.panel__eyebrow {
	margin-bottom: var(--space-2);
	color: var(--brand);
	font-size: 0.78rem;
	font-weight: 800;
	letter-spacing: 0.14em;
	text-transform: uppercase;
}

.panel__title {
	margin-bottom: var(--space-2);
	font-family: var(--font-display);
	font-size: clamp(1.1rem, 1rem + 0.9vw, 1.55rem);
	line-height: 1.1;
}

.panel__subtitle {
	margin: 0;
	color: var(--text-muted);
	line-height: 1.5;
}

.hero {
	display: grid;
	grid-template-columns: minmax(0, 1.5fr) minmax(320px, 1fr);
	gap: var(--space-6);
	background:
		radial-gradient(circle at top right, rgba(255, 255, 255, 0.72), transparent 42%),
		linear-gradient(145deg, rgba(255, 248, 241, 0.98), rgba(247, 236, 222, 0.94));
	border-color: var(--border-strong);
	box-shadow: var(--shadow-lg);
}

.hero__title {
	margin: 0 0 var(--space-3);
	font-family: var(--font-display);
	font-size: clamp(2rem, 1.6rem + 1.8vw, 3.35rem);
	line-height: 0.98;
	letter-spacing: -0.02em;
}

.hero__lead {
	margin: 0;
	max-width: 68ch;
	color: var(--text-muted);
	font-size: 1.03rem;
	line-height: 1.6;
}

.hero__metrics {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: var(--space-3);
	align-content: start;
}

.metric-card {
	padding: var(--space-4);
	border-radius: var(--radius-lg);
	border: 1px solid var(--border-muted);
	background: rgba(255, 255, 255, 0.72);
}

.metric-card__label {
	display: block;
	margin-bottom: var(--space-2);
	color: var(--text-soft);
	font-size: 0.76rem;
	font-weight: 800;
	letter-spacing: 0.12em;
	text-transform: uppercase;
}

.metric-card__value {
	display: block;
	margin-bottom: var(--space-1);
	font-family: var(--font-display);
	font-size: clamp(1.7rem, 1.2rem + 1vw, 2.3rem);
	line-height: 1;
}

.metric-card__detail {
	color: var(--text-muted);
	font-size: 0.92rem;
}

.dashboard__top-grid {
	display: grid;
	grid-template-columns: minmax(0, 1.6fr) minmax(280px, 1fr);
	gap: var(--space-6);
}

.panel--builder {
	overflow: hidden;
}

.builder__layout {
	display: grid;
	grid-template-columns: minmax(260px, 320px) minmax(0, 1fr);
	gap: var(--space-5);
	align-items: start;
}

.builder__palette,
.builder__workspace {
	display: grid;
	gap: var(--space-4);
}

.builder__palette-title {
	font-family: var(--font-display);
	font-size: 1.06rem;
}

.builder__palette-copy,
.builder__hint {
	margin: 0;
	color: var(--text-muted);
	line-height: 1.5;
}

.builder__palette-list {
	display: grid;
	gap: var(--space-3);
}

.builder__palette-button {
	justify-content: flex-start;
	gap: var(--space-3);
	min-height: 72px;
	padding: var(--space-3) var(--space-4);
	text-align: left;
	border-radius: var(--radius-md);
	cursor: grab;
}

.builder__palette-button:active {
	cursor: grabbing;
}

.builder__palette-symbol,
.diagram-block__symbol,
.diagram-empty .builder__palette-symbol {
	font-family: Consolas, "Cascadia Mono", "Courier New", monospace;
	font-size: 1.15rem;
	letter-spacing: 0.02em;
	white-space: nowrap;
}

.builder__palette-button > span:last-child {
	display: grid;
	gap: var(--space-1);
	text-align: left;
}

.builder__palette-description {
	display: block;
	color: var(--text-muted);
	font-size: 0.88rem;
	font-weight: 500;
	line-height: 1.4;
}

.builder__footer,
.builder__workspace-header {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	gap: var(--space-3);
	flex-wrap: wrap;
}

.diagram-canvas {
	padding: var(--space-5);
	border: 1px solid #b8b8b8;
	border-radius: var(--radius-lg);
	background:
		linear-gradient(rgba(15, 15, 15, 0.05) 1px, transparent 1px),
		linear-gradient(90deg, rgba(15, 15, 15, 0.05) 1px, transparent 1px),
		#fff;
	background-size: 24px 24px;
	transition: border-color 160ms ease, background-color 160ms ease;
	min-height: 254px;
}

.diagram-canvas--active {
	border-color: var(--accent);
	background:
		linear-gradient(rgba(39, 75, 105, 0.1) 1px, transparent 1px),
		linear-gradient(90deg, rgba(39, 75, 105, 0.1) 1px, transparent 1px),
		#fff;
	background-size: 24px 24px;
}

.diagram-rung {
	display: grid;
	grid-template-columns: 14px minmax(0, 1fr) 14px;
	gap: var(--space-4);
	align-items: stretch;
	min-height: 190px;
}

.diagram-rung__rail {
	align-self: stretch;
	justify-self: center;
	width: 5px;
	border-radius: 999px;
	background: linear-gradient(180deg, #222, #555);
}

.diagram-rung__track {
	display: flex;
	align-items: center;
	gap: var(--space-2);
	overflow-x: auto;
	padding-bottom: var(--space-2);
	min-height: 190px;
}

.diagram-rung__group {
	display: flex;
	align-items: stretch;
	gap: var(--space-2);
	min-height: 100%;
}

.diagram-drop-slot {
	width: 22px;
	min-width: 22px;
	border-radius: 999px;
	border: 1px dashed transparent;
	background: transparent;
	transition: background-color 120ms ease, border-color 120ms ease;
}

.diagram-drop-slot--active {
	background: rgba(39, 75, 105, 0.16);
	border-color: var(--accent);
}

.diagram-block {
	display: grid;
	gap: var(--space-2);
	min-width: 170px;
	padding: var(--space-3);
	border: 1px solid #bbb;
	border-radius: 16px;
	background: rgba(255, 255, 255, 0.95);
	cursor: grab;
	box-shadow: 0 4px 10px rgba(28, 28, 28, 0.04);
}

.diagram-block:active {
	cursor: grabbing;
}

.diagram-block__header,
.diagram-block__meta {
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: var(--space-3);
	flex-wrap: wrap;
}

.diagram-block__type {
	font-family: var(--font-display);
	font-size: 0.92rem;
	letter-spacing: 0.04em;
}

.diagram-block__symbol-wrap {
	position: relative;
	display: grid;
	place-items: center;
	padding: var(--space-2) var(--space-1);
	min-height: 76px;
	border: 1px solid #ddd;
	border-radius: var(--radius-sm);
	background: #fff;
}

.diagram-block__symbol-wrap::before,
.diagram-block__symbol-wrap::after {
	content: "";
	position: absolute;
	top: 50%;
	width: 18px;
	height: 2px;
	background: #111;
	transform: translateY(-50%);
}

.diagram-block__symbol-wrap::before {
	left: -18px;
}

.diagram-block__symbol-wrap::after {
	right: -18px;
}

.diagram-symbol {
	width: 100%;
	height: 64px;
	overflow: visible;
	color: #153047;
}

.diagram-symbol--energized {
	color: #d97706;
}

.diagram-symbol--pushbutton-no {
	color: #16a34a;
}

.diagram-symbol--pushbutton-nc {
	color: #dc2626;
}

.diagram-symbol--estop {
	color: #dc2626;
}

.diagram-symbol--ol {
	color: #ea580c;
}

.diagram-symbol__line {
	stroke: currentColor;
	stroke-width: 3.5;
	fill: none;
	stroke-linecap: round;
	stroke-linejoin: round;
}

.diagram-symbol__breaker-lead {
	stroke-width: 3.5;
}

.diagram-symbol__shape {
	stroke: currentColor;
	stroke-width: 3.5;
	fill: rgba(255, 255, 255, 0.94);
}

.diagram-symbol__terminal {
	stroke: currentColor;
	stroke-width: 3.5;
	fill: rgba(255, 255, 255, 0.98);
}

.diagram-symbol__linkage {
	stroke: currentColor;
	stroke-width: 2.8;
	fill: none;
	stroke-linecap: round;
	stroke-dasharray: 3 3;
	opacity: 1;
}

.diagram-symbol__fill {
	fill: currentColor;
}

/* Trazos vectoriales del usuario: el arte de referencia viene con lineas de
   ~1.2 unidades, asi que el contorno se engrosa con stroke (2 unidades del
   viewBox 128x64) hasta el peso 3.2 que usa el resto de los simbolos. El
   relleno se dibuja aparte, exacto, para no cerrar los huecos decorativos. */
.diagram-symbol__vector {
	fill: currentColor;
	stroke: none;
}

.diagram-symbol__vector--normalized {
	fill: currentColor;
	stroke: currentColor;
	stroke-linecap: butt;
	stroke-linejoin: miter;
}

.diagram-symbol__vector--outline {
	fill: none;
	stroke: currentColor;
	stroke-linecap: round;
	stroke-linejoin: round;
}

/* Anillos de bornes dibujados como trazo (SPST): mismo relleno que los
   terminales del resto de simbolos. */
.diagram-symbol__vector-ring {
	stroke: currentColor;
	fill: rgba(255, 255, 255, 0.98);
}

.diagram-symbol__coil-core {
	fill: rgba(20, 184, 166, 0.18);
	opacity: 0;
	transform-origin: 64px 30px;
	transform-box: fill-box;
	transition: opacity 140ms ease, transform 140ms ease, fill 140ms ease;
}

.diagram-symbol__contact-arm,
.diagram-symbol__contact-slash {
	transform-origin: 64px 30px;
	transform-box: fill-box;
	transition: transform 140ms ease, stroke 140ms ease, opacity 140ms ease;
}

.diagram-symbol__text {
	fill: currentColor;
	font-size: 11.5px;
	font-family: "Aptos", "Segoe UI Variable", "Segoe UI", sans-serif;
	font-weight: 800;
	letter-spacing: 0.06em;
}

.diagram-symbol__terminal-label {
	fill: currentColor;
	font-size: 9px;
	font-family: "Aptos", "Segoe UI Variable", "Segoe UI", sans-serif;
	font-weight: 700;
	letter-spacing: 0;
}

.diagram-symbol--energized .diagram-symbol__shape {
	fill: rgba(254, 243, 199, 0.54);
}

.diagram-symbol--coil-active {
	color: #d97706;
}

.diagram-symbol--coil-active .diagram-symbol__shape {
	fill: rgba(254, 243, 199, 0.74);
	stroke: currentColor;
}

.diagram-symbol--coil-active .diagram-symbol__coil-core {
	opacity: 1;
	fill: rgba(250, 204, 21, 0.24);
	transform: scale(1.05);
}

.diagram-symbol--contact-closed {
	color: #0f766e;
}

.diagram-symbol--contact-closed .diagram-symbol__contact-arm {
	stroke-width: 3.5;
}

.diagram-symbol--contact-actuated .diagram-symbol__contact-arm,
.diagram-symbol--contact-actuated .diagram-symbol__contact-slash {
	stroke: #ea580c;
	transform: scale(1.04);
}

.diagram-symbol__motor-rotor {
	transform-origin: 64px 32px;
	transform-box: fill-box;
	will-change: transform;
}

.diagram-block__symbol-fallback {
	font-family: Consolas, "Cascadia Mono", "Courier New", monospace;
	font-size: 0.8rem;
	color: var(--text-soft);
	text-align: center;
}

.diagram-block__remove {
	min-height: 30px;
	padding: 0.35rem 0.7rem;
}

.diagram-block__field {
	display: grid;
	gap: 0.35rem;
}

.diagram-block__select {
	min-height: 38px;
	padding: 0 var(--space-3);
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-sm);
	background: var(--bg-surface-strong);
	color: var(--text-strong);
	font-size: 0.92rem;
}

.diagram-block__tag {
	color: var(--text-muted);
	font-weight: 700;
	line-height: 1.4;
}

.diagram-empty {
	display: grid;
	place-items: center;
	gap: var(--space-3);
	width: 100%;
	padding: var(--space-6);
	border: 1px dashed var(--border-muted);
	border-radius: var(--radius-md);
	background: rgba(255, 255, 255, 0.54);
	color: var(--text-muted);
	text-align: center;
	cursor: copy;
}

.project-panel__toolbar {
	display: flex;
	flex-wrap: wrap;
	align-items: end;
	gap: var(--space-4);
}

.field {
	display: grid;
	gap: var(--space-2);
	min-width: 240px;
	flex: 1 1 280px;
}

.field__label {
	color: var(--text-muted);
	font-size: 0.78rem;
	font-weight: 800;
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.select {
	min-height: 48px;
	padding: 0 var(--space-4);
	border: 1px solid var(--border-muted);
	background: var(--bg-surface-strong);
	color: var(--text-strong);
}

.project-panel__actions {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-3);
}

.button {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-height: 46px;
	padding: 0 var(--space-4);
	border: 1px solid transparent;
	background: var(--bg-surface-muted);
	color: var(--text-strong);
	font-weight: 800;
	letter-spacing: 0.01em;
	cursor: pointer;
	transition:
		transform 160ms ease,
		box-shadow 160ms ease,
		border-color 160ms ease,
		background-color 160ms ease;
}

.button:hover:not(:disabled) {
	transform: translateY(-1px);
	box-shadow: 0 10px 20px rgba(71, 43, 23, 0.12);
}

.button--primary {
	background: linear-gradient(180deg, var(--brand), var(--brand-deep));
	color: #fff;
}

.button--secondary {
	background: linear-gradient(180deg, var(--accent), var(--accent-deep));
	color: #fff;
}

.button--ghost {
	border-color: var(--border-strong);
	background: transparent;
}

.button--danger {
	background: linear-gradient(180deg, #c6583f, var(--danger));
	color: #fff;
}

.button--small {
	min-height: 40px;
	padding: 0 var(--space-3);
	font-size: 0.92rem;
}

.project-panel__summary {
	display: grid;
	gap: var(--space-3);
	margin-top: var(--space-5);
	padding: var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-lg);
	background: rgba(255, 255, 255, 0.58);
}

.project-panel__summary-title {
	font-family: var(--font-display);
	font-size: 1.18rem;
}

.project-panel__summary-copy {
	color: var(--text-muted);
	line-height: 1.55;
}

.notice {
	margin-top: var(--space-5);
	padding: var(--space-4);
	border-radius: var(--radius-md);
	border: 1px solid var(--border-muted);
	font-weight: 700;
	line-height: 1.45;
}

.notice--info {
	background: rgba(239, 246, 255, 0.92);
	border-color: #c2d6eb;
	color: #274b69;
}

.notice--error {
	background: var(--danger-bg);
	border-color: #edc2b6;
	color: #8a2d1d;
}

.guide-list {
	list-style: none;
	padding: 0;
	margin: 0;
	display: grid;
	gap: var(--space-4);
}

.guide-list__item {
	display: grid;
	grid-template-columns: auto 1fr;
	gap: var(--space-3);
}

.guide-list__index {
	display: grid;
	place-items: center;
	width: 34px;
	height: 34px;
	border-radius: 50%;
	background: linear-gradient(180deg, var(--brand), var(--brand-deep));
	color: #fff;
	font-weight: 800;
}

.guide-list__title {
	margin-bottom: var(--space-1);
	font-size: 1rem;
}

.guide-list__body {
	margin: 0;
	color: var(--text-muted);
	line-height: 1.5;
}

.status-pill {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-height: 34px;
	padding: 0 var(--space-3);
	border-radius: 999px;
	border: 1px solid transparent;
	font-size: 0.85rem;
	font-weight: 800;
}

.status-pill--on {
	background: var(--success-bg);
	border-color: #c0e6d0;
	color: var(--success);
}

.status-pill--off {
	background: rgba(245, 237, 226, 0.95);
	border-color: var(--border-muted);
	color: var(--text-muted);
}

.status-pill--danger {
	background: var(--danger-bg);
	border-color: #edc2b6;
	color: var(--danger);
}

.status-pill--neutral {
	background: rgba(255, 255, 255, 0.68);
	border-color: var(--border-muted);
	color: var(--text-muted);
}

.detail-chip {
	display: inline-flex;
	align-items: center;
	min-height: 30px;
	padding: 0 var(--space-3);
	border: 1px solid var(--border-muted);
	border-radius: 999px;
	background: rgba(255, 255, 255, 0.68);
	color: var(--text-muted);
	font-size: 0.83rem;
	font-weight: 700;
}

.detail-chip--on {
	border-color: #c4e4d0;
	background: #f4fff8;
	color: var(--success);
}

.detail-chip--off {
	border-color: var(--border-muted);
	color: var(--text-muted);
}

.detail-chip--pending {
	border-color: #f0d7a5;
	background: var(--warning-bg);
	color: var(--warning);
}

.panel--controls .panel__header {
	margin-bottom: var(--space-4);
}

.control-panel__stats {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-2);
}

.control-panel__body {
	display: grid;
	grid-template-columns: auto minmax(0, 1fr);
	gap: var(--space-5);
	align-items: start;
}

.control-panel__actions {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-3);
}

.scan-cycle {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: var(--space-3);
}

.scan-cycle__step {
	padding: var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-md);
	background: var(--bg-surface-strong);
}

.scan-cycle__step--live {
	border-color: rgba(39, 75, 105, 0.35);
	box-shadow: inset 0 0 0 1px rgba(39, 75, 105, 0.15);
}

.scan-cycle__label {
	margin-bottom: var(--space-2);
	font-family: var(--font-display);
	font-size: 1rem;
}

.scan-cycle__text {
	margin: 0;
	color: var(--text-muted);
	line-height: 1.45;
}

.dashboard__main-grid {
	display: grid;
	grid-template-columns: minmax(0, 1.8fr) minmax(320px, 0.95fr);
	gap: var(--space-6);
	align-items: start;
}

.dashboard__workspace,
.dashboard__sidebar {
	display: grid;
	gap: var(--space-6);
}

.summary-grid {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: var(--space-3);
}

.summary-card {
	padding: var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-md);
	background: rgba(255, 255, 255, 0.62);
}

.summary-card__label {
	display: block;
	margin-bottom: var(--space-2);
	color: var(--text-soft);
	font-size: 0.76rem;
	font-weight: 800;
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.summary-card__value {
	font-family: var(--font-display);
	font-size: 1.45rem;
}

.empty-state {
	margin: 0;
	padding: var(--space-4);
	border: 1px dashed var(--border-strong);
	border-radius: var(--radius-md);
	background: rgba(255, 255, 255, 0.48);
	color: var(--text-muted);
	line-height: 1.5;
}

.ladder-rungs,
.trace-list,
.tag-groups,
.tag-list {
	display: grid;
	gap: var(--space-4);
}

.ladder-rung,
.trace-rung,
.tag-card {
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-lg);
	background: rgba(255, 255, 255, 0.6);
}

.ladder-rung {
	padding: var(--space-5);
}

.ladder-rung__meta,
.trace-rung__header,
.tag-card__header,
.tag-group__header,
.trace-step__headline {
	display: flex;
	justify-content: space-between;
	gap: var(--space-3);
	align-items: flex-start;
}

.ladder-rung__index {
	margin-bottom: var(--space-1);
	color: var(--text-soft);
	font-size: 0.8rem;
	font-weight: 800;
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.ladder-rung__title,
.trace-rung__title,
.tag-group__title {
	margin: 0;
	font-family: var(--font-display);
	font-size: 1.12rem;
}

.trace-rung__subtitle,
.tag-group__subtitle {
	margin: var(--space-1) 0 0;
	color: var(--text-muted);
	line-height: 1.45;
}

.ladder-rung__lane {
	display: grid;
	grid-template-columns: 14px minmax(0, 1fr) 14px;
	gap: var(--space-3);
	align-items: stretch;
}

.ladder-rung__rail {
	align-self: stretch;
	justify-self: center;
	width: 4px;
	min-height: 132px;
	border-radius: 999px;
	background: linear-gradient(180deg, #d3b898, #a88458);
}

.ladder-rung__instructions {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
	gap: var(--space-3);
}

.instruction-card {
	display: grid;
	gap: var(--space-3);
	min-height: 168px;
	padding: var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-md);
	background: var(--bg-surface-strong);
}

.instruction-card--energized {
	background: linear-gradient(180deg, #f2fff7, #e6f8ee);
	border-color: #b8dcc6;
	box-shadow: inset 0 0 0 1px rgba(24, 122, 81, 0.12);
}

.instruction-card__header {
	display: flex;
	justify-content: space-between;
	gap: var(--space-3);
	align-items: flex-start;
}

.instruction-card__type {
	font-family: var(--font-display);
	font-size: 1.06rem;
}

.instruction-card__label {
	font-weight: 800;
	line-height: 1.35;
}

.instruction-card__description,
.trace-step__summary,
.tag-card__description {
	margin: 0;
	color: var(--text-muted);
	line-height: 1.5;
}

.instruction-card__tag,
.trace-step__tag,
.tag-card__name {
	color: var(--text-soft);
	font-size: 0.84rem;
}

.instruction-card__chips,
.trace-step__badges {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-2);
	margin-top: auto;
}

.tag-group {
	display: grid;
	gap: var(--space-3);
}

.tag-card {
	padding: var(--space-4);
	display: grid;
	gap: var(--space-3);
}

.tag-card--input {
	border-left: 4px solid var(--accent);
}

.tag-card--output {
	border-left: 4px solid var(--brand);
}

.tag-card--internal {
	border-left: 4px solid #6d5d49;
}

.tag-card__title {
	margin: 0 0 var(--space-1);
	font-size: 1rem;
}

.tag-card__footer {
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: var(--space-3);
	flex-wrap: wrap;
}

.tag-card__kind {
	color: var(--text-soft);
	font-size: 0.76rem;
	font-weight: 800;
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.trace-rung {
	padding: var(--space-4);
}

.trace-steps {
	display: grid;
	gap: var(--space-3);
}

.trace-step {
	padding: var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: var(--radius-md);
	background: var(--bg-surface-strong);
}

.trace-step__title {
	margin: 0;
	font-weight: 800;
}

.builder-freeplay {
	display: grid;
	grid-template-columns: minmax(208px, 240px) minmax(0, 1fr) minmax(240px, 292px);
	gap: var(--space-4);
	align-items: start;
}

.builder-sidebar {
	display: contents;
}

.builder-card {
	display: grid;
	gap: var(--space-3);
	padding: var(--space-4);
	border: 1px solid rgba(34, 52, 72, 0.1);
	border-radius: 22px;
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(249, 250, 252, 0.9));
	box-shadow: 0 18px 38px rgba(31, 41, 55, 0.08);
	backdrop-filter: blur(12px);
	transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.builder-card--active {
	border-color: rgba(30, 64, 175, 0.22);
	box-shadow: 0 20px 42px rgba(30, 64, 175, 0.12);
}

.builder-card--tools,
.builder-card--components {
	grid-column: 1;
}

.builder-card--tools {
	position: sticky;
	top: var(--space-4);
	align-self: start;
}

.builder-card--components-docked {
	grid-column: auto;
	width: 100%;
	max-height: none;
	overflow: hidden;
	align-self: stretch;
	position: relative;
	top: auto;
	padding: 1rem;
	border-radius: 24px;
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 250, 252, 0.94));
	box-shadow: 0 18px 38px rgba(31, 41, 55, 0.08);
}

.builder-card--components-horizontal {
	gap: 0.85rem;
}

.builder-right-rail {
	grid-column: 3;
	grid-row: 1 / span 2;
	display: grid;
	gap: var(--space-3);
	align-self: start;
	min-width: 0;
}

.builder-card--properties {
	max-height: none;
	overflow-y: auto;
	position: relative;
	top: auto;
}

.builder-card__title {
	font-family: var(--font-display);
	font-size: 1.02rem;
	letter-spacing: 0.06em;
}

.builder-card__copy,
.builder-stage__hint {
	margin: 0;
	color: var(--text-muted);
	line-height: 1.5;
}

.builder-mode-switch,
.builder-stage__status {
	display: flex;
	gap: var(--space-2);
	flex-wrap: wrap;
	align-items: center;
}

.builder-action-row {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: var(--space-2);
}

.builder-mode-button {
	flex: 1 1 0;
	min-height: 44px;
}

.builder-color-field {
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: var(--space-3);
}

.builder-wire-settings {
	display: grid;
	gap: 0.8rem;
	padding: 0.9rem 1rem;
	border-radius: 18px;
	background: linear-gradient(180deg, rgba(246, 249, 252, 0.9), rgba(239, 244, 249, 0.76));
	border: 1px solid rgba(34, 52, 72, 0.08);
}

.builder-wire-settings__label {
	margin: 0;
	font-size: 0.74rem;
	font-weight: 800;
	letter-spacing: 0.09em;
	text-transform: uppercase;
	color: var(--text-muted);
}

.builder-slider-field {
	display: grid;
	gap: 0.45rem;
}

.builder-slider-row {
	display: grid;
	grid-template-columns: minmax(0, 1fr) auto;
	gap: var(--space-3);
	align-items: center;
}

.builder-slider-input {
	width: 100%;
	accent-color: #1d4ed8;
	cursor: pointer;
}

.builder-slider-value {
	min-width: 3.6rem;
	text-align: right;
	color: var(--text-strong);
	font-weight: 800;
}

.builder-color-input {
	width: 64px;
	height: 42px;
	padding: 0;
	border: none;
	background: transparent;
	cursor: pointer;
}

.builder-number-input {
	min-width: 0;
	width: 100%;
	min-height: 48px;
	padding: 0 var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: 14px;
	background: var(--bg-surface-strong);
	color: var(--text-strong);
	font-weight: 700;
}

.builder-text-input {
	min-height: 46px;
	padding: 0 var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: 14px;
	background: var(--bg-surface-strong);
	color: var(--text-strong);
	font-weight: 700;
	outline: none;
	transition: border-color 140ms ease, box-shadow 140ms ease;
}

.builder-select-input {
	min-height: 46px;
	padding: 0 var(--space-4);
	border: 1px solid var(--border-muted);
	border-radius: 14px;
	background: var(--bg-surface-strong);
	color: var(--text-strong);
	font-weight: 700;
	outline: none;
	transition: border-color 140ms ease, box-shadow 140ms ease;
}

.builder-text-input:focus {
	border-color: rgba(37, 99, 235, 0.44);
	box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.14);
}

.builder-select-input:focus {
	border-color: rgba(37, 99, 235, 0.44);
	box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.14);
}

.builder-palette-list {
	display: grid;
	gap: 0.75rem;
	max-height: min(46vh, 520px);
	overflow-y: auto;
	padding-right: 0.3rem;
}

.builder-palette-list--horizontal {
	display: flex;
	gap: 0.75rem;
	max-height: none;
	overflow-x: auto;
	overflow-y: hidden;
	padding-right: 0;
	padding-bottom: 0.25rem;
	scrollbar-width: thin;
}

.builder-palette-list::-webkit-scrollbar,
.builder-card--properties::-webkit-scrollbar {
	width: 10px;
}

.builder-palette-list--horizontal::-webkit-scrollbar {
	height: 10px;
	width: auto;
}

.builder-palette-list::-webkit-scrollbar-thumb,
.builder-card--properties::-webkit-scrollbar-thumb {
	border-radius: 999px;
	background: rgba(148, 163, 184, 0.42);
}

.builder-palette-tile {
	display: grid;
	grid-template-columns: 110px minmax(0, 1fr);
	align-items: center;
	gap: var(--space-3);
	padding: var(--space-3);
	text-align: left;
	min-height: 112px;
	border: 1px solid rgba(34, 52, 72, 0.08);
	border-radius: 20px;
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(245, 247, 250, 0.92));
	transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
	user-select: none;
}

.builder-palette-tile--horizontal {
	flex: 0 0 240px;
	min-height: 96px;
	padding: 0.85rem;
	grid-template-columns: 84px minmax(0, 1fr);
	align-self: stretch;
}

.builder-palette-tile__symbol {
	display: grid;
	place-items: center;
	width: 100%;
	min-height: 84px;
	padding: 0.5rem;
	border-radius: 18px;
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(241, 245, 249, 0.96));
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), inset 0 0 0 1px rgba(15, 23, 42, 0.04);
}

.builder-palette-tile__symbol .diagram-symbol {
	height: 74px;
}

.builder-palette-tile__symbol--power,
.freeplay-component__symbol-rotator--power {
	color: #b45309;
}

.builder-palette-tile__symbol--breaker,
.freeplay-component__symbol-rotator--breaker {
	color: #0f766e;
}

.builder-palette-tile__symbol--load,
.freeplay-component__symbol-rotator--load {
	color: #92400e;
}

.builder-palette-tile__symbol--contact,
.freeplay-component__symbol-rotator--contact {
	color: #1d4ed8;
}

.builder-palette-tile__symbol--coil,
.freeplay-component__symbol-rotator--coil {
	color: #b91c1c;
}

.builder-palette-tile__info {
	display: grid;
	gap: 0.32rem;
	justify-items: start;
	min-width: 0;
}

.builder-palette-tile__label {
	font-weight: 800;
	color: var(--text-strong);
}

.builder-palette-tile__copy {
	font-size: 0.86rem;
	line-height: 1.45;
	color: var(--text-muted);
}

.builder-palette-tile:hover {
	transform: translateY(-1px);
	border-color: rgba(29, 78, 216, 0.14);
	box-shadow: 0 14px 30px rgba(30, 41, 59, 0.08);
}

.builder-palette-tile--selected {
	border-color: rgba(29, 78, 216, 0.22);
	box-shadow: 0 18px 36px rgba(29, 78, 216, 0.12);
	transform: translateX(4px);
}

.builder-rules {
	display: grid;
	gap: 0.75rem;
}

.builder-props-grid {
	display: grid;
	grid-template-columns: auto minmax(0, 1fr);
	gap: 0.7rem 1rem;
	align-items: center;
	padding: 0.95rem 1rem;
	border-radius: 18px;
	background: linear-gradient(180deg, rgba(246, 249, 252, 0.9), rgba(239, 244, 249, 0.76));
	border: 1px solid rgba(34, 52, 72, 0.08);
}

.builder-wire-status {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-2);
	align-items: center;
}

.builder-props-label {
	font-size: 0.74rem;
	font-weight: 800;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--text-muted);
}

.builder-props-value {
	justify-self: end;
	text-align: right;
	color: var(--text-strong);
	font-weight: 800;
}

.builder-selection__row {
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: var(--space-3);
	color: var(--text-muted);
}

.builder-selection__row strong {
	color: var(--text-strong);
	font-weight: 800;
}

.builder-selection__actions {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: var(--space-2);
}

.builder-properties-fields {
	display: grid;
	gap: 0.9rem;
}

.builder-terminal-fields {
	display: grid;
	gap: 0.65rem;
}

.builder-terminal-fields__grid {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));
	gap: var(--space-2);
}

.builder-terminal-field {
	display: grid;
	gap: 0.35rem;
}

.builder-terminal-field__label {
	font-size: 0.74rem;
	font-weight: 800;
	letter-spacing: 0.04em;
	color: var(--text-muted);
	text-transform: uppercase;
}

.builder-selection__action-button {
	min-height: 42px;
}

.builder-selection__swatch {
	width: 28px;
	height: 18px;
	border-radius: 999px;
	border: 1px solid rgba(15, 23, 42, 0.14);
	box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.5);
	justify-self: end;
}

.builder-wire-endpoints {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--space-3);
}

.builder-wire-endpoint {
	display: grid;
	gap: 0.7rem;
	padding: 0.95rem;
	border-radius: 18px;
	border: 1px solid rgba(34, 52, 72, 0.08);
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(242, 245, 249, 0.94));
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.builder-wire-endpoint--connected {
	border-color: rgba(22, 163, 74, 0.16);
	background: linear-gradient(180deg, rgba(243, 252, 247, 0.96), rgba(238, 249, 243, 0.94));
}

.builder-wire-endpoint--loose {
	border-color: rgba(220, 38, 38, 0.12);
	background: linear-gradient(180deg, rgba(255, 248, 248, 0.96), rgba(252, 243, 243, 0.94));
}

.builder-wire-endpoint__header {
	display: flex;
	justify-content: space-between;
	gap: var(--space-2);
	align-items: center;
}

.builder-wire-endpoint__label {
	font-size: 0.72rem;
	font-weight: 800;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--text-muted);
}

.builder-wire-endpoint__title {
	display: block;
	font-size: 0.98rem;
	line-height: 1.3;
	color: var(--text-strong);
}

.builder-wire-endpoint__detail {
	margin: 0;
	font-size: 0.85rem;
	line-height: 1.45;
	color: var(--text-muted);
}

.builder-wire-endpoint__actions {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(132px, 1fr));
	gap: var(--space-2);
}

.builder-wire-actions {
	display: grid;
	grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
	gap: var(--space-2);
}

.builder-wire-endpoint__actions .button,
.builder-wire-actions .button {
	min-height: 40px;
}

.builder-rule {
	display: flex;
	gap: 0.7rem;
	align-items: flex-start;
	color: var(--text-muted);
	line-height: 1.45;
}

.builder-rule__dot {
	width: 10px;
	height: 10px;
	border-radius: 999px;
	background: var(--accent);
	margin-top: 0.35rem;
	flex: 0 0 auto;
}

.builder-stage {
	display: grid;
	grid-template-rows: auto minmax(0, 1fr);
	gap: var(--space-3);
	min-width: 0;
	min-height: calc(100vh - 12rem);
	align-content: start;
	grid-column: 2;
	grid-row: 1 / span 2;
}

.builder-stage__top-row {
	display: grid;
	grid-template-columns: minmax(0, 1fr);
	gap: var(--space-3);
	align-items: start;
}

.builder-stage__state-panel {
	display: grid;
	gap: var(--space-3);
	padding: var(--space-3);
	border: 1px solid rgba(34, 52, 72, 0.08);
	border-radius: 22px;
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(248, 249, 251, 0.92));
	box-shadow: 0 16px 34px rgba(31, 41, 55, 0.06);
	position: relative;
	top: auto;
	align-self: start;
	max-height: none;
	overflow: hidden;
}

.builder-stage__state-panel--sidebar {
	position: sticky;
	top: var(--space-4);
	max-height: calc(100vh - var(--space-8));
	overflow-y: auto;
}

.builder-stage__state-actions {
	display: grid;
	gap: var(--space-2);
	position: sticky;
	top: 0;
	padding-bottom: var(--space-2);
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 249, 251, 0.96));
	z-index: 1;
}

.builder-stage__state-copy {
	display: grid;
	gap: 0.75rem;
	min-width: 0;
}

.builder-palette-drag-preview {
	position: fixed;
	left: 0;
	top: 0;
	width: 168px;
	padding: 0.5rem;
	display: grid;
	gap: 0.45rem;
	border-radius: 20px;
	border: 1px solid rgba(37, 99, 235, 0.2);
	background: rgba(255, 255, 255, 0.96);
	box-shadow: 0 14px 30px rgba(15, 23, 42, 0.14);
	color: var(--text-strong);
	pointer-events: none;
	transform: translate(-50%, -50%);
	will-change: transform, left, top;
	z-index: 40;
}

.builder-palette-drag-preview__symbol {
	min-height: 90px;
	padding: 0.35rem;
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.92), inset 0 0 0 1px rgba(15, 23, 42, 0.05);
}

.builder-palette-drag-preview__symbol .diagram-symbol {
	height: 78px;
	width: 100%;
}

.builder-palette-drag-preview__label {
	padding: 0 0.25rem 0.1rem;
	text-align: center;
	font-size: 0.78rem;
	font-weight: 800;
	letter-spacing: 0.04em;
	color: var(--text-strong);
}

.builder-stage__toolbar {
	display: flex;
	justify-content: space-between;
	align-items: flex-start;
	gap: var(--space-3);
	flex-wrap: wrap;
	min-width: 0;
	padding: var(--space-3);
	border: 1px solid rgba(34, 52, 72, 0.08);
	border-radius: 22px;
	background: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 249, 251, 0.9));
	box-shadow: 0 16px 34px rgba(31, 41, 55, 0.06);
}

.builder-stage__toolbar-copy {
	display: grid;
	gap: 0.75rem;
	flex: 1 1 540px;
	min-width: 0;
}

.builder-stage__notice {
	margin: 0;
	padding: 0.85rem 1rem;
	border-radius: 18px;
	border: 1px solid rgba(34, 52, 72, 0.08);
	line-height: 1.5;
	color: var(--text-strong);
	background: linear-gradient(180deg, rgba(246, 249, 252, 0.94), rgba(239, 244, 249, 0.82));
}

.builder-stage__notice strong {
	font-weight: 800;
}

.builder-stage__notice--error {
	border-color: rgba(220, 38, 38, 0.16);
	background: linear-gradient(180deg, rgba(255, 245, 245, 0.98), rgba(252, 238, 238, 0.94));
	color: #991b1b;
}

.builder-stage__notice--info {
	border-color: rgba(29, 78, 216, 0.14);
	background: linear-gradient(180deg, rgba(245, 249, 255, 0.98), rgba(236, 244, 255, 0.94));
}

.builder-stage__run-button {
	min-width: 132px;
	min-height: 48px;
	align-self: stretch;
}

.builder-stage__run-button--prominent,
.builder-stage__run-button--secondary {
	width: 100%;
	min-height: 52px;
}

.builder-stage__toolbar-actions {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-3);
	align-items: stretch;
}

.builder-stage__zoom-controls {
	display: flex;
	flex-wrap: wrap;
	gap: var(--space-2);
	align-items: center;
}

.builder-stage__zoom-controls--panel {
	justify-content: flex-start;
}

.builder-stage__zoom-button {
	min-height: 40px;
}

.builder-stage__zoom-readout {
	min-width: 4.5rem;
	justify-content: center;
}

.builder-stage__scroll {
	overflow: auto;
	min-height: 0;
	height: clamp(480px, calc(100vh - 18rem), 860px);
	padding: 0;
	border: 1px solid rgba(34, 52, 72, 0.08);
	border-radius: 28px;
	background: linear-gradient(180deg, rgba(253, 252, 248, 0.96), rgba(246, 248, 252, 0.92));
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.92);
	overscroll-behavior: contain;
	scrollbar-color: rgba(100, 116, 139, 0.55) transparent;
	scrollbar-width: thin;
}

.builder-stage__scroll::-webkit-scrollbar {
	height: 12px;
	width: 12px;
}

.builder-stage__scroll::-webkit-scrollbar-track {
	background: transparent;
}

.builder-stage__scroll::-webkit-scrollbar-thumb {
	border: 2px solid transparent;
	border-radius: 999px;
	background: rgba(100, 116, 139, 0.45);
	background-clip: padding-box;
}

.builder-stage__scroll::-webkit-scrollbar-thumb:hover {
	background: rgba(100, 116, 139, 0.65);
	background-clip: padding-box;
}

.builder-stage__scroll--hand,
.builder-stage__scroll--hand *,
.freeplay-canvas--hand,
.freeplay-canvas--hand * {
	cursor: grab !important;
}

.builder-stage__scroll--panning,
.builder-stage__scroll--panning *,
.freeplay-canvas--panning,
.freeplay-canvas--panning * {
	cursor: grabbing !important;
}

.builder-stage__scroll--pan,
.freeplay-canvas--pan {
	cursor: grab;
	user-select: none;
}

.builder-stage__scroll--panning,
.freeplay-canvas--panning {
	cursor: grabbing;
}

.freeplay-canvas-viewport {
	position: relative;
	min-width: 0;
	min-height: 0;
}

.freeplay-canvas {
	position: absolute;
	width: 1720px;
	height: 940px;
	overflow: hidden;
	border-radius: 28px;
	/* Sin border: con box-sizing:border-box el contenido media 2 px menos que
	   el viewBox del SVG y todos los cables se escalaban ~0.9979 (el error
	   crecia con la Y). El borde se dibuja con box-shadow, que no ocupa layout. */
	border: 0;
	transform-origin: top left;
	background:
		radial-gradient(circle at top left, rgba(255, 255, 255, 0.95), transparent 28%),
		linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(246, 247, 251, 0.98));
	box-shadow:
		inset 0 0 0 1px rgba(134, 148, 166, 0.5),
		inset 0 1px 0 rgba(255, 255, 255, 0.95),
		inset 0 0 0 1px rgba(255, 255, 255, 0.55);
}

/* Sheet layer: the SVG grid is the only grid; it shares gridSpacing with grid.ts snap. */
.sheet-grid__line {
	pointer-events: none;
	stroke-linecap: square;
	vector-effect: non-scaling-stroke;
}

.sheet-grid__line--minor {
	stroke: rgba(15, 23, 42, 0.05);
	stroke-width: 1;
	opacity: var(--grid-minor-opacity, 1);
}

.sheet-grid__line--major {
	stroke: rgba(30, 41, 59, 0.12);
	stroke-width: 1;
}

.sheet-frame {
	fill: none;
	pointer-events: none;
	stroke: rgba(30, 41, 59, 0.45);
	stroke-width: 2;
}

.sheet-zone-label {
	fill: rgba(30, 41, 59, 0.55);
	font-size: 10px;
	font-weight: 600;
	pointer-events: none;
	user-select: none;
}

.sheet-title-block__frame {
	fill: rgba(255, 255, 255, 0.85);
	stroke: rgba(30, 41, 59, 0.45);
	stroke-width: 1.5;
}

.sheet-title-block__label {
	fill: rgba(30, 41, 59, 0.55);
	font-size: 10px;
	font-weight: 600;
	pointer-events: none;
	user-select: none;
}

.sheet-title-block__value {
	fill: rgba(15, 23, 42, 0.9);
	font-size: 12px;
	pointer-events: none;
	user-select: none;
}

.freeplay-canvas--wire {
	cursor: crosshair;
}

.freeplay-canvas--wire.freeplay-canvas--panning {
	cursor: grabbing;
}

.freeplay-plane-overlay {
	position: absolute;
	inset: 0;
	pointer-events: none;
	z-index: 1;
}

.freeplay-axis {
	position: absolute;
	background: linear-gradient(180deg, rgba(30, 64, 175, 0.58), rgba(37, 99, 235, 0.76));
	box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.8), 0 6px 14px rgba(37, 99, 235, 0.12);
	opacity: 0.94;
}

.freeplay-axis--x {
	left: 0;
	right: 0;
	top: 0;
	height: 3px;
}

.freeplay-axis--y {
	left: 0;
	top: 0;
	bottom: 0;
	width: 3px;
}

.freeplay-axis__label,
.freeplay-plane-origin {
	position: absolute;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	min-height: 24px;
	padding: 0.12rem 0.5rem;
	border-radius: 999px;
	background: rgba(255, 255, 255, 0.92);
	border: 1px solid rgba(37, 99, 235, 0.18);
	box-shadow: 0 8px 16px rgba(15, 23, 42, 0.08);
	color: #1d4ed8;
	font-size: 0.72rem;
	font-weight: 800;
	letter-spacing: 0.08em;
	text-transform: uppercase;
}

.freeplay-axis__label--x {
	right: 0.9rem;
	top: 0.55rem;
}

.freeplay-axis__label--y {
	left: 0.65rem;
	bottom: 0.75rem;
}

.freeplay-plane-origin {
	left: 0.65rem;
	top: 0.55rem;
	color: #0f172a;
	letter-spacing: 0.04em;
	text-transform: none;
}

.freeplay-svg {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	overflow: visible;
	z-index: 2;
}

.freeplay-wire {
	fill: none;
	stroke-linecap: round;
	stroke-linejoin: round;
	stroke-width: 3.5;
}

.freeplay-wire--selected {
	stroke: #1d4ed8;
}

.freeplay-wire--draft {
	stroke-dasharray: 10 6;
	opacity: 0.85;
}

.freeplay-wire--energized {
	stroke: #f59e0b;
	stroke-dasharray: 12 7;
}

.freeplay-wire--energized-ac {
	animation: freeplay-wire-flow-ac 0.95s ease-in-out infinite;
}

.freeplay-wire--energized-dc {
	animation: freeplay-wire-flow-dc 1.15s linear infinite;
}

.freeplay-wire--idle {
	stroke-dasharray: 7 9;
	opacity: 0.72;
	filter: drop-shadow(0 0 7px rgba(96, 165, 250, 0.18));
}

.freeplay-wire--idle-ac {
	stroke: #60a5fa;
	animation: freeplay-wire-flow-ac 1.25s ease-in-out infinite;
}

.freeplay-wire--idle-dc {
	stroke: #fb923c;
	animation: freeplay-wire-flow-dc 1.45s linear infinite;
}

.freeplay-wire__hit {
	fill: none;
	stroke: transparent;
	stroke-linecap: round;
	stroke-linejoin: round;
	stroke-width: 18;
	cursor: pointer;
}

.freeplay-wire__node {
	fill: #fff;
	stroke-width: 2;
	transition: fill 120ms ease, filter 120ms ease, stroke-width 120ms ease;
}

.freeplay-debug-overlay {
	position: absolute;
	inset: 0;
	z-index: 4;
	pointer-events: none;
}

.freeplay-terminal-debug {
	fill: #e11d48;
	stroke: #ffffff;
	stroke-width: 1;
	pointer-events: none;
}

.freeplay-terminal-debug--stub {
	fill: #0e7490;
}

.freeplay-wire__snap-marker {
	fill: rgba(14, 116, 144, 0.16);
	stroke: #0e7490;
	stroke-width: 2;
	stroke-dasharray: 2 2;
	pointer-events: none;
}

.freeplay-wire__node--selected {
	cursor: grab;
	filter: drop-shadow(0 0 10px rgba(29, 78, 216, 0.18));
}

.freeplay-wire__node--selected:active {
	cursor: grabbing;
}

.freeplay-wire__node--endpoint {
	stroke-width: 2.4;
}

.freeplay-wire__node--bend {
	opacity: 0.96;
}

.freeplay-component {
	position: absolute;
	width: 160px;
	min-height: 136px;
	padding: 0;
	border: 0;
	border-radius: 16px;
	background: transparent;
	box-shadow: none;
	display: grid;
	justify-items: center;
	align-content: start;
	gap: 0.2rem;
	user-select: none;
	z-index: 3;
	pointer-events: none;
}

.freeplay-component--tight {
	display: block;
	min-height: 0;
	grid-template: none;
	justify-items: initial;
	align-content: initial;
	overflow: visible;
}

.freeplay-component__logical-stage {
	display: contents;
}

.freeplay-component--tight > .freeplay-component__logical-stage {
	display: block;
	position: absolute;
}

.freeplay-component--selected {
	border-color: transparent;
	background: transparent;
	box-shadow: none;
}

.freeplay-component__glyph {
	position: relative;
	width: 100%;
	min-height: 102px;
	display: grid;
	place-items: center;
	pointer-events: none;
}

.freeplay-component__timer-indicator {
	position: absolute;
	left: 50%;
	top: 0.55rem;
	transform: translateX(-50%);
	display: grid;
	gap: 0.22rem;
	min-width: 4.9rem;
	padding: 0.28rem 0.45rem;
	border-radius: 14px;
	background: rgba(255, 255, 255, 0.96);
	border: 1px solid rgba(37, 99, 235, 0.16);
	box-shadow: 0 10px 18px rgba(37, 99, 235, 0.1);
	pointer-events: none;
	z-index: 2;
}

.freeplay-component__timer-label {
	font-size: 0.66rem;
	font-weight: 800;
	letter-spacing: 0.04em;
	text-align: center;
	color: #1d4ed8;
	font-variant-numeric: tabular-nums;
}

.freeplay-component__timer-track {
	position: relative;
	display: block;
	height: 0.28rem;
	border-radius: 999px;
	background: rgba(191, 219, 254, 0.7);
	overflow: hidden;
}

.freeplay-component__timer-fill {
	display: block;
	height: 100%;
	border-radius: inherit;
	background: linear-gradient(90deg, #60a5fa, #2563eb);
	transition: width 120ms linear;
}

.freeplay-component__glyph-handle {
	position: absolute;
	left: 50%;
	top: 50%;
	transform: translate(-50%, -50%);
	border-radius: 18px;
	background: transparent;
	pointer-events: none;
	z-index: 1;
}

.freeplay-selector-hitarea {
	position: absolute;
	left: 0;
	top: 0;
	width: 160px;
	height: 102px;
	transform-origin: 50% 50%;
	background: transparent;
	border: 0;
	box-shadow: none;
	cursor: pointer;
	pointer-events: auto;
	z-index: 1;
}


.freeplay-component__symbol-rotator {
	display: grid;
	place-items: center;
	width: 100%;
	/* Debe coincidir con COMPONENT_GLYPH_HEIGHT (102): la proyeccion de los
	   terminales centra el glifo en 102 px. Con 96 el cable quedaba 3 px por
	   encima de la pata de todos los simbolos. */
	height: 102px;
	padding: 0;
	position: relative;
	transition: transform 140ms ease;
	transform-origin: center;
	/* Sin filter: crea una capa de composicion separada del SVG de cables y a
	   zoom/scroll fraccionarios el glifo se desplaza medio pixel. */
	pointer-events: none;
}

.freeplay-component--manual:hover .freeplay-component__symbol-rotator,
.freeplay-component__press-target:hover ~ .freeplay-component__symbol-rotator,
.freeplay-component--manual-active .freeplay-component__symbol-rotator {
	opacity: 0.98;
}

.freeplay-component__hit-shapes {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	overflow: visible;
	pointer-events: none;
}

.freeplay-component__hit-shape {
	cursor: grab;
}

.freeplay-component__hit-shape:active {
	cursor: grabbing;
}

.freeplay-component--manual .freeplay-component__hit-shape {
	cursor: pointer;
}

.freeplay-component--manual .freeplay-component__hit-shape:active {
	cursor: grabbing;
}

.freeplay-component--selector-ring-hover .freeplay-component__hit-shape {
	cursor: default;
}

.freeplay-component__hit-debug-bounds {
	position: absolute;
	outline: 1px dashed rgba(220, 38, 38, 0.9);
	outline-offset: 1px;
	pointer-events: none;
	z-index: 4;
}

.freeplay-component__glyph .diagram-symbol {
	height: 84px;
	width: 100%;
}

.freeplay-component--energized .freeplay-component__symbol-rotator,
.freeplay-component--coil-on .freeplay-component__symbol-rotator,
.freeplay-component--contact-active .freeplay-component__symbol-rotator,
.freeplay-component--pushbutton-down .freeplay-component__symbol-rotator {
	/* El estado se comunica con color/clase; sin capas de filtro. */
	opacity: 0.98;
}

.freeplay-component__press-target {
	position: absolute;
	left: 50%;
	top: 28px;
	width: 68px;
	height: 46px;
	transform: translate(-50%, -50%);
	border: none;
	background: transparent;
	padding: 0;
	margin: 0;
	z-index: 2;
	cursor: pointer;
	pointer-events: auto;
}

.freeplay-component__badge,
.freeplay-component__label-row,
.freeplay-port {
	pointer-events: auto;
}

.freeplay-component__press-target:focus-visible {
	outline: 2px solid rgba(14, 116, 144, 0.42);
	outline-offset: 2px;
	border-radius: 12px;
}

.freeplay-component--lamp-on .diagram-symbol__shape {
	fill: var(--lamp-glow-fill, rgba(250, 204, 21, 0.4));
	stroke: var(--lamp-glow-stroke, #ca8a04);
}

.freeplay-component--coil-on .diagram-symbol__line,
.freeplay-component--coil-on .diagram-symbol__text,
.freeplay-component--coil-on .diagram-symbol__shape,
.freeplay-component--contact-closed .diagram-symbol__line,
.freeplay-component--contact-closed .diagram-symbol__text,
.freeplay-component--contact-active .diagram-symbol__line,
.freeplay-component--contact-active .diagram-symbol__text,
.freeplay-component--lamp-on .diagram-symbol__line,
.freeplay-component--lamp-on .diagram-symbol__text,
.freeplay-component--motor-on .diagram-symbol__line,
.freeplay-component--motor-on .diagram-symbol__text,
.freeplay-component--motor-on .diagram-symbol__shape {
	color: var(--lamp-symbol-color, #d97706);
	stroke: currentColor;
}

.freeplay-component--motor-on .diagram-symbol__line,
.freeplay-component--motor-on .diagram-symbol__text,
.freeplay-component--motor-on .diagram-symbol__shape {
	color: #d97706;
}

.freeplay-component--motor-on .diagram-symbol__motor-rotor {
	animation: diagram-motor-spin 1.45s linear infinite;
}

.freeplay-component__badge {
	position: absolute;
	left: 50%;
	top: -0.55rem;
	transform: translateX(-50%);
	padding: 0.18rem 0.55rem;
	border-radius: 999px;
	background: rgba(255, 255, 255, 0.96);
	border: 1px solid rgba(15, 23, 42, 0.08);
	box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
	font-size: 0.72rem;
	font-weight: 800;
	letter-spacing: 0.04em;
	color: var(--text-strong);
	z-index: 3;
}

.freeplay-component__badge--live {
	background: linear-gradient(180deg, rgba(255, 244, 214, 0.98), rgba(254, 231, 176, 0.96));
	border-color: rgba(245, 158, 11, 0.22);
	color: #9a3412;
}

.freeplay-component__badge--timer {
	background: linear-gradient(180deg, rgba(239, 246, 255, 0.98), rgba(219, 234, 254, 0.94));
	border-color: rgba(37, 99, 235, 0.18);
	color: #1d4ed8;
	font-variant-numeric: tabular-nums;
	min-width: 4.8rem;
}

.freeplay-component__label-row {
	position: absolute;
	left: 0;
	right: 0;
	display: flex;
	justify-content: center;
	padding: 0 0.3rem;
}

.freeplay-component__label-row--debug {
	outline: 1px dashed rgba(220, 38, 38, 0.9);
	outline-offset: 2px;
}

.freeplay-component__label,
.freeplay-component__label-input {
	max-width: 150px;
	width: 100%;
	padding: 0.22rem 0.55rem;
	font-size: 0.8rem;
	font-weight: 700;
	line-height: 1.35;
	text-align: center;
	color: var(--text-strong);
	background: rgba(255, 255, 255, 0.9);
	border-radius: 999px;
	box-shadow: 0 4px 12px rgba(15, 23, 42, 0.06);
}

.freeplay-component__label {
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.freeplay-component__label-input {
	border: 1px solid rgba(29, 78, 216, 0.18);
	background: rgba(255, 255, 255, 0.96);
	outline: none;
}

.freeplay-component-menu {
	position: absolute;
	z-index: 6;
	display: flex;
	flex-direction: column;
	gap: 0.15rem;
	min-width: 9.5rem;
	padding: 0.3rem;
	background: rgba(255, 255, 255, 0.98);
	border: 1px solid rgba(29, 78, 216, 0.18);
	border-radius: 0.5rem;
	box-shadow: 0 10px 24px rgba(15, 23, 42, 0.16);
}

.freeplay-component-menu__action {
	padding: 0.32rem 0.6rem;
	font-size: 0.8rem;
	font-weight: 600;
	text-align: left;
	color: var(--text-strong);
	background: transparent;
	border-radius: 0.35rem;
	cursor: pointer;
}

.freeplay-wire-menu {
	min-width: 11rem;
}

.freeplay-wire-menu__row {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 0.5rem;
	padding: 0.3rem 0.6rem;
	font-size: 0.78rem;
	color: #334155;
}

.freeplay-wire-menu__label {
	font-weight: 700;
}

.freeplay-wire-menu__color {
	width: 2.1rem;
	height: 1.4rem;
	padding: 0;
	border: 1px solid rgba(15, 23, 42, 0.18);
	border-radius: 0.35rem;
	background: transparent;
	cursor: pointer;
}

.freeplay-wire-menu__thickness {
	display: inline-flex;
	gap: 0.2rem;
}

.freeplay-wire-menu__thickness-button {
	padding: 0.12rem 0.38rem;
	font-size: 0.72rem;
	font-weight: 600;
	color: #334155;
	background: #f8fafc;
	border: 1px solid rgba(15, 23, 42, 0.16);
	border-radius: 0.35rem;
	cursor: pointer;
}

.freeplay-wire-menu__thickness-button--active {
	color: #0e7490;
	background: rgba(14, 116, 144, 0.12);
	border-color: rgba(14, 116, 144, 0.45);
}

.freeplay-component-menu__action:hover {
	background: rgba(37, 99, 235, 0.1);
}

.freeplay-component-menu__input {
	width: 100%;
	max-width: none;
}

.freeplay-toast {
	position: fixed;
	left: 50%;
	bottom: 28px;
	z-index: 1200;
	max-width: min(520px, calc(100vw - 32px));
	padding: 10px 16px;
	color: #f8fafc;
	font-size: 0.82rem;
	font-weight: 600;
	text-align: center;
	background: rgba(15, 23, 42, 0.94);
	border: 1px solid rgba(148, 163, 184, 0.28);
	border-radius: 999px;
	box-shadow: 0 12px 30px rgba(15, 23, 42, 0.24);
	transform: translateX(-50%);
	pointer-events: none;
	animation: freeplay-toast-in 120ms ease-out;
}

@keyframes freeplay-toast-in {
	from {
		opacity: 0;
		transform: translate(-50%, 6px);
	}
	to {
		opacity: 1;
		transform: translate(-50%, 0);
	}
}

.context-menu {
	position: fixed;
	z-index: 1000;
	display: flex;
	flex-direction: column;
	gap: 2px;
	min-width: 180px;
	max-width: min(320px, calc(100vw - 16px));
	max-height: calc(100vh - 16px);
	padding: 6px;
	overflow-x: hidden;
	overflow-y: auto;
	background: rgba(255, 255, 255, 0.99);
	border: 1px solid rgba(29, 78, 216, 0.18);
	border-radius: 10px;
	box-shadow: 0 14px 36px rgba(15, 23, 42, 0.2);
	transition:
		opacity 80ms ease,
		transform 80ms ease;
}

.context-menu--closing {
	opacity: 0;
	pointer-events: none;
	transform: translateY(-3px);
}

.context-menu--submenu {
	min-width: 190px;
}

.context-menu__item {
	display: grid;
	grid-template-columns: 16px 14px minmax(0, 1fr) auto;
	align-items: center;
	gap: 8px;
	min-height: 32px;
	padding: 0 8px;
	color: var(--text-strong);
	font-size: 0.82rem;
	font-weight: 600;
	text-align: left;
	background: transparent;
	border: 0;
	border-radius: 6px;
	cursor: pointer;
}

.context-menu__item:hover,
.context-menu__item:focus-visible {
	background: rgba(37, 99, 235, 0.1);
	outline: none;
}

.context-menu__item--danger {
	color: #b91c1c;
}

.context-menu__item--danger:hover {
	background: rgba(220, 38, 38, 0.1);
}

.context-menu__check {
	width: 16px;
	color: #0e7490;
	font-size: 0.78rem;
	text-align: center;
}

.context-menu__icon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 14px;
	height: 14px;
}

.context-menu__swatch {
	width: 14px;
	height: 14px;
	border: 1px solid rgba(15, 23, 42, 0.18);
	border-radius: 999px;
}

.context-menu__label {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.context-menu__shortcut {
	color: #64748b;
	font-size: 0.7rem;
	font-weight: 600;
}

.context-menu__separator {
	height: 1px;
	margin: 4px 6px;
	background: rgba(15, 23, 42, 0.1);
}

.context-menu__field {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 10px;
	min-height: 32px;
	padding: 0 8px;
	color: #334155;
	font-size: 0.78rem;
}

.context-menu__field input[type="color"] {
	width: 34px;
	height: 22px;
	padding: 0;
	background: transparent;
	border: 1px solid rgba(15, 23, 42, 0.18);
	border-radius: 6px;
	cursor: pointer;
}

.context-menu__thickness {
	display: inline-flex;
	gap: 3px;
}

.context-menu__thickness button {
	min-width: 26px;
	padding: 2px 5px;
	font-size: 0.7rem;
	font-weight: 600;
	background: #f8fafc;
	border: 1px solid rgba(15, 23, 42, 0.16);
	border-radius: 5px;
	cursor: pointer;
}

.context-menu__thickness button.context-menu__thickness--active {
	color: #0e7490;
	background: rgba(14, 116, 144, 0.12);
	border-color: rgba(14, 116, 144, 0.45);
}

.context-menu__input {
	width: 100%;
	min-height: 34px;
	padding: 0 8px;
	background: #fff;
	border: 1px solid rgba(29, 78, 216, 0.25);
	border-radius: 6px;
	outline: none;
}

@media (pointer: coarse) {
	.context-menu__item {
		min-height: 44px;
	}

	.context-menu__field {
		min-height: 44px;
	}

	.context-menu__thickness button {
		min-width: 44px;
		min-height: 44px;
	}
}

.command-palette__backdrop {
	position: fixed;
	inset: 0;
	z-index: 1300;
	display: flex;
	align-items: flex-start;
	justify-content: center;
	padding: 10vh 1rem 1rem;
	background: rgba(15, 23, 42, 0.28);
}

.command-palette {
	display: flex;
	flex-direction: column;
	width: min(640px, 100%);
	max-height: 70vh;
	overflow: hidden;
	background: #fff;
	border: 1px solid rgba(29, 78, 216, 0.18);
	border-radius: 14px;
	box-shadow: 0 24px 60px rgba(15, 23, 42, 0.28);
}

.command-palette__input {
	flex: 0 0 auto;
	min-height: 48px;
	padding: 0 1rem;
	color: var(--text-strong);
	font-size: 0.95rem;
	font-weight: 600;
	background: #fff;
	border: 0;
	border-bottom: 1px solid rgba(34, 52, 72, 0.1);
	outline: none;
}

.command-palette__input::placeholder {
	color: var(--text-soft);
}

.command-palette__list {
	display: flex;
	flex: 1 1 auto;
	flex-direction: column;
	min-height: 0;
	padding: 0.35rem;
	overflow-y: auto;
}

.command-palette__item {
	display: grid;
	grid-template-columns: 20px minmax(0, 1fr) auto;
	align-items: center;
	gap: 0.6rem;
	min-height: 40px;
	padding: 0 0.65rem;
	color: var(--text-strong);
	font-size: 0.82rem;
	font-weight: 700;
	text-align: left;
	background: transparent;
	border: 0;
	border-radius: 8px;
	cursor: pointer;
}

.command-palette__item:hover,
.command-palette__item--active {
	background: rgba(37, 99, 235, 0.1);
}

.command-palette__item--disabled {
	opacity: 0.45;
	cursor: not-allowed;
}

.command-palette__icon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 20px;
	height: 20px;
}

.command-palette__label {
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.command-palette__shortcut {
	color: #64748b;
	font-size: 0.7rem;
	font-weight: 600;
}

.command-palette__empty {
	margin: 0;
	padding: 1rem;
	color: var(--text-muted);
	font-size: 0.82rem;
}

.command-palette__footer {
	flex: 0 0 auto;
	padding: 0.45rem 1rem;
	color: var(--text-soft);
	font-size: 0.68rem;
	border-top: 1px solid rgba(34, 52, 72, 0.08);
}

@media (pointer: coarse) {
	.command-palette__item {
		min-height: 44px;
	}
}

.freeplay-terminal-label-input {
	position: absolute;
	min-width: 2.4rem;
	max-width: 4.8rem;
	padding: 0.16rem 0.38rem;
	font-size: 0.68rem;
	font-weight: 700;
	line-height: 1.2;
	text-align: center;
	color: var(--text-strong);
	background: rgba(255, 255, 255, 0.98);
	border: 1px solid rgba(29, 78, 216, 0.22);
	border-radius: 999px;
	box-shadow: 0 4px 12px rgba(15, 23, 42, 0.08);
	transform: translate(-50%, -50%);
	z-index: 4;
	outline: none;
}

.freeplay-terminal-label-input:focus {
	border-color: rgba(37, 99, 235, 0.5);
	box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.18);
}

.freeplay-port {
	position: absolute;
	width: 18px;
	height: 18px;
	border-radius: 999px;
	border: 0;
	background: transparent;
	transform: translate(-50%, -50%);
	padding: 0;
	z-index: 2;
	box-shadow: none;
	opacity: 1;
	cursor: default;
	transition:
		transform 140ms ease,
		box-shadow 140ms ease,
		opacity 140ms ease;
}

.freeplay-port--active {
	box-shadow: none;
	opacity: 1;
	cursor: crosshair;
}

.freeplay-port--active:hover {
	transform: translate(-50%, -50%);
	box-shadow: 0 0 0 4px rgba(39, 75, 105, 0.14);
}

.freeplay-port--connections-locked {
	cursor: not-allowed;
}

.freeplay-port--connections-locked:hover {
	transform: translate(-50%, -50%);
	box-shadow: none;
}

@keyframes freeplay-wire-flow-ac {
	0% {
		stroke-dashoffset: -18;
	}
	50% {
		stroke-dashoffset: 18;
	}
	100% {
		stroke-dashoffset: -18;
	}
}

@keyframes freeplay-wire-flow-dc {
	from {
		stroke-dashoffset: 0;
	}
	to {
		stroke-dashoffset: -38;
	}
}

@keyframes diagram-motor-spin {
	from {
		transform: rotate(0deg);
	}
	to {
		transform: rotate(360deg);
	}
}

@media (max-width: 1180px) {
	.hero,
	.builder-freeplay,
	.builder__layout,
	.dashboard__top-grid,
	.dashboard__main-grid,
	.control-panel__body {
		grid-template-columns: 1fr;
	}

	.builder-wire-endpoints {
		grid-template-columns: 1fr;
	}

	.builder-stage__top-row {
		grid-template-columns: 1fr;
	}

	.builder-card--tools,
	.builder-right-rail,
	.builder-stage {
		grid-column: auto;
		grid-row: auto;
	}

	.builder-card--components-docked {
		width: 100%;
		max-height: none;
	}

	.builder-card--tools,
	.builder-right-rail,
	.builder-stage__state-panel--sidebar,
	.builder-card--properties {
		position: relative;
		top: auto;
		max-height: none;
	}

	.builder-stage__state-actions {
		position: relative;
	}
}

@media (max-width: 860px) {
	.app-shell {
		padding: var(--space-5) var(--space-3) var(--space-7);
	}

	.panel {
		padding: var(--space-5);
	}

	.hero__metrics,
	.summary-grid {
		grid-template-columns: 1fr 1fr;
	}

	.builder-palette-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}

	.diagram-rung {
		grid-template-columns: 1fr;
	}

	.diagram-rung__rail {
		display: none;
	}

	.ladder-rung__lane {
		grid-template-columns: 1fr;
	}

	.ladder-rung__rail {
		display: none;
	}

	.scan-cycle {
		grid-template-columns: 1fr;
	}
}

@media (max-width: 620px) {
	.hero__metrics,
	.summary-grid {
		grid-template-columns: 1fr;
	}

	.project-panel__actions,
	.control-panel__actions {
		width: 100%;
	}

	.button {
		width: 100%;
	}

	.project-panel__toolbar {
		align-items: stretch;
	}

	.field {
		min-width: 100%;
	}

	.diagram-block {
		min-width: 200px;
	}
}

/* Builder ribbon shell */
.app-shell--playground {
