.ribbon-tabs-row {
	display: flex;
	align-items: flex-end;
	gap: 0.5rem;
	padding: 0 1rem;
}

.ribbon-tabs {
	display: flex;
	gap: 0.15rem;
	overflow-x: auto;
	scrollbar-width: none;
}

.ribbon-tabs::-webkit-scrollbar {
	display: none;
}

.ribbon-tab {
	border: 0;
	border-bottom: 2px solid transparent;
	background: transparent;
	color: var(--text-muted);
	font-size: 0.76rem;
	font-weight: 800;
	min-height: 40px;
	padding: 0.4rem 0.7rem;
