	background: rgba(255, 255, 255, 0.8);
	color: var(--text-muted);
	cursor: pointer;
	font-size: 0.8rem;
	line-height: 1;
	padding: 0.3rem 0.55rem;
}

.ribbon-collapse-button:hover {
	color: var(--text-strong);
	border-color: rgba(37, 99, 235, 0.3);
}

.ribbon-body {
