.ribbon-group {
	display: flex;
	flex-direction: column;
	gap: 0.3rem;
	min-width: 0;
	padding: 0 0.65rem;
	border-right: 1px solid rgba(34, 52, 72, 0.08);
}

.ribbon-group:last-child {
	border-right: 0;
}

.ribbon-group__label {
	color: var(--text-soft);
	font-size: 0.62rem;
	font-weight: 800;
	letter-spacing: 0.1em;
	text-transform: uppercase;
}

.ribbon-group__body {
	display: flex;
	flex-wrap: wrap;
	align-items: flex-start;
	gap: 0.3rem;
}

.ribbon-group--compact {
	position: relative;
	border-right: 0;
}

.ribbon-group--compact > summary {
	list-style: none;
	cursor: pointer;
	padding: 0.3rem 0.5rem;
	border: 1px solid rgba(34, 52, 72, 0.12);
	border-radius: 8px;
	background: rgba(255, 255, 255, 0.8);
}

.ribbon-group--compact > summary::-webkit-details-marker {
	display: none;
}

.ribbon-group--compact[open] > summary {
	color: var(--brand);
	border-color: rgba(37, 99, 235, 0.3);
	background: rgba(37, 99, 235, 0.08);
}

.ribbon-group--compact > .ribbon-group__body {
	position: absolute;
